/**
 * Generates docs/reference/cli.md from the real CLI (help text + rule list).
 *
 * The reference is a build artifact committed to the repo: CI regenerates it
 * and fails on any diff, so docs can never describe flags that do not exist.
 * Never hand-edit the generated file — change the CLI, regenerate, commit.
 *
 * Usage:
 *   node scripts/gen-cli-docs.mjs          # regenerate docs/reference/cli.md
 *   node scripts/gen-cli-docs.mjs --check  # exit 1 if the committed file is stale
 * Requires `dist/` (run `pnpm run build` first).
 */
import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

const ROOT = process.cwd();
const OUT = path.join(ROOT, 'docs/reference/cli.md');

function run(args) {
  try {
    return execFileSync('node', ['dist/cli.js', ...args], { encoding: 'utf8', cwd: ROOT });
  } catch {
    console.error('gen-cli-docs: dist/cli.js failed — run `pnpm run build` first.');
    process.exit(2);
  }
}

// NOTE: the blank line after the HTML comment is load-bearing — prettier
// inserts it, and the --check gate compares bytes, so the generator must
// emit prettier-stable output or the two CI jobs fight each other forever.
const doc =
  '<!-- GENERATED by scripts/gen-cli-docs.mjs — do not hand-edit. -->\n' +
  '\n' +
  '# CLI reference (generated)\n' +
  '\n' +
  'Regenerated from the built CLI. If this file disagrees with `--help`, ' +
  'the file is stale — run `node scripts/gen-cli-docs.mjs` and commit.\n' +
  '\n' +
  '## `usa --help`\n' +
  '\n' +
  '```\n' +
  run(['--help']).trimEnd() +
  '\n```\n' +
  '\n' +
  '## `usa rules`\n' +
  '\n' +
  '```\n' +
  run(['rules']).trimEnd() +
  '\n```\n';

// A document generated from a partial rule load is worse than no document: it
// silently drops packs and then looks authoritative. CI has twice produced a
// `usa rules` listing 25 of 32 packs (the last seven stack packs missing), which
// `--check` reported only as "stale" and the resync job then committed.
// Compare against the index — the source of truth for how many packs should load
// — and refuse to emit anything if they disagree.
const indexRaw = fs.readFileSync(path.join(ROOT, 'rules/index.yaml'), 'utf8');
const expectedPacks = (indexRaw.match(/^\s*-\s+\S+\.yaml\s*$/gm) ?? []).length;
const summary = /(\d+) rule\(s\) across (\d+) pack\(s\)\./.exec(doc);
if (!summary) {
  console.error('gen-cli-docs: could not find the "N rule(s) across M pack(s)" summary.');
  process.exit(2);
}
const loadedPacks = Number(summary[2]);
if (expectedPacks > 0 && loadedPacks !== expectedPacks) {
  console.error(
    `gen-cli-docs: usa rules loaded ${loadedPacks} of ${expectedPacks} packs from rules/index.yaml.`,
  );
  console.error(
    '  Refusing to write a document generated from a partial rule load — it would ' +
      'silently drop packs and then read as authoritative.',
  );
  process.exit(2);
}

if (process.argv.includes('--check')) {
  const current = fs.existsSync(OUT) ? fs.readFileSync(OUT, 'utf8') : null;
  if (current !== doc) {
    console.error(
      'docs/reference/cli.md is stale — run `node scripts/gen-cli-docs.mjs` and commit the result.',
    );
    // Diagnose rather than merely assert. This gate has failed on CI while
    // passing locally, on PRs that cannot affect the CLI (a workflow-only
    // change), and passed on a re-run of the same commit. A bare "is stale"
    // message makes that indistinguishable from real drift, so the failure
    // carries its own evidence: sizes, the first differing line, and the
    // generated output on disk for a full diff.
    console.error(`  committed: ${current === null ? 'missing' : `${current.length} bytes`}`);
    console.error(`  generated: ${doc.length} bytes`);
    if (current !== null) {
      const a = current.split('\n');
      const b = doc.split('\n');
      for (let i = 0; i < Math.max(a.length, b.length); i += 1) {
        if (a[i] !== b[i]) {
          console.error(`  first difference at line ${i + 1}:`);
          console.error(`    committed: ${JSON.stringify(a[i] ?? '<missing>')}`);
          console.error(`    generated: ${JSON.stringify(b[i] ?? '<missing>')}`);
          break;
        }
      }
    }
    // Where the generated output *stops* matters as much as where it first
    // differs: a shorter file that ends mid-section is a truncation, while one
    // that ends cleanly is a content change.
    const generatedLines = doc.split('\n');
    console.error(`  generated ends: ${JSON.stringify(generatedLines.slice(-3))}`);
    const expected = path.join(os.tmpdir(), 'cli.md.generated');
    fs.writeFileSync(expected, doc);
    console.error(`  generated output: ${expected}  (diff it against ${path.relative(ROOT, OUT)})`);
    process.exit(1);
  }
  console.log('CLI reference: OK (in sync)');
} else {
  fs.writeFileSync(OUT, doc);
  console.log(`wrote ${path.relative(ROOT, OUT)}`);
}
